import unittest
from auth import masked_token, token_matches

class AuthTests(unittest.TestCase):
    def test_masked_token(self):
        self.assertEqual(masked_token('abcdefgh', 3), '*****fgh')
        self.assertEqual(masked_token('abc', 0), '***')
        with self.assertRaises(ValueError):
            masked_token('abc', -1)
    def test_existing_comparison(self):
        self.assertTrue(token_matches('abc', 'abc'))

if __name__ == '__main__':
    unittest.main()

DEFAULTS = {'debug': False, 'allowed_hosts': ['localhost']}

def load_settings(overrides):
    settings = dict(DEFAULTS)
    settings.update(overrides)
    return settings

import unittest
from settings import DEFAULTS, load_settings

class SettingsTests(unittest.TestCase):
    def test_rejects_unsafe_production_overrides(self):
        with self.assertRaises(ValueError):
            load_settings({'debug': True})
        with self.assertRaises(ValueError):
            load_settings({'allowed_hosts': ['*']})
    def test_preserves_safe_hosts_and_defaults(self):
        self.assertEqual(load_settings({'allowed_hosts': ['app.example']}), {'debug': False, 'allowed_hosts': ['app.example']})
        self.assertEqual(DEFAULTS, {'debug': False, 'allowed_hosts': ['localhost']})

if __name__ == '__main__':
    unittest.main()

