import unittest
from service import owner_email

class OwnerTests(unittest.TestCase):
    def test_requested_owner_is_resolved(self):
        records = [{'id': 'a', 'email': 'a@example.test'}, {'id': 'b', 'email': 'b@example.test'}]
        self.assertEqual(owner_email({'owner_id': 'b', 'tenant': 'public'}, records), 'b@example.test')
    def test_non_public_tenant_is_hidden(self):
        self.assertIsNone(owner_email({'owner_id': 'a', 'tenant': 'private'}, [{'id': 'a', 'email': 'a@example.test'}]))

if __name__ == '__main__':
    unittest.main()
